const prototypeFrames={enterprise:document.querySelector('#enterprise-frame'),police:document.querySelector('#police-frame')};
function showPrototype(){const view=location.hash==='#police'?'police':'enterprise';for(const [name,frame] of Object.entries(prototypeFrames)){frame.hidden=name!==view}const selected=prototypeFrames[view];if(selected.getAttribute('src')==='about:blank'){selected.src=view==='police'?'jingzhen-plan2.html?embedded=1&v=20261021-unified':'enterprise.html?embedded=1&v=20261021-unified'+(location.hash==='#enterprise-topic'?'#enterprise-topic':'')}document.querySelectorAll('[data-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===view)));document.title='西小联 · '+(view==='police'?'经侦端':'企业端')+'原型'}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{location.hash=button.dataset.view}));window.addEventListener('hashchange',showPrototype);showPrototype();
